public class InnerMemoryEpisodicMemoryStrategyFactory(Action<Humidifier.BedrockAgentCore.MemoryTypes.EpisodicMemoryStrategy> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.MemoryTypes.EpisodicMemoryStrategy>
{

    internal InnerMemoryEpisodicReflectionConfigurationInputFactory ReflectionConfigurationFactory { get; set; }

    internal InnerMemoryMemoryRecordSchemaFactory MemoryRecordSchemaFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.MemoryTypes.EpisodicMemoryStrategy Create()
    {
        var episodicMemoryStrategyResult = CreateEpisodicMemoryStrategy();
        factoryAction?.Invoke(episodicMemoryStrategyResult);

        return episodicMemoryStrategyResult;
    }

    private Humidifier.BedrockAgentCore.MemoryTypes.EpisodicMemoryStrategy CreateEpisodicMemoryStrategy()
    {
        var episodicMemoryStrategyResult = new Humidifier.BedrockAgentCore.MemoryTypes.EpisodicMemoryStrategy();

        return episodicMemoryStrategyResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.MemoryTypes.EpisodicMemoryStrategy result)
    {
        base.CreateChildren(result);

        result.ReflectionConfiguration ??= ReflectionConfigurationFactory?.Build();
        result.MemoryRecordSchema ??= MemoryRecordSchemaFactory?.Build();
    }

} // End Of Class

